201	Extra Options (require additional license):
202	  --ilm       <image>         Load ILM ROM image
203	  --dlm       <image>         Load DLM ROM image
204	  --hvm       <image>         Load HVM (High-Bandwidth Vector Memory) image
205	  --waveform  <file>          Enable VCD/FST waveform tracing
206	  --save                      Save context when CPU enters WFI
207	  --continue                  Restore context and resume execution
208	  --context-dir <dir>         Context directory [default: ./saved_ctx]
209	
210	Hybrid (QEMU + Verilator):
211	  --shared-mem-path <file>    mmap-backed file used as main RAM (zero-copy
212	                              shared with QEMU). Requires --shared-mem-size.
213	  --shared-mem-size <bytes>   Size of the shared mmap region; must cover the
214	                              full main memory range
215	  --shared-mem-base <hex>     Guest physical address that file offset 0 maps
216	                              to. Default 0x80000000 (QEMU virt RAM base);
217	                              override only for non-virt machine types.
218	  --resume-from-qemu <file>   Resume from a QEMU-side state snapshot.
219	                              Mutually exclusive with --continue.
220	  --handoff-out <file>        Drain architectural state to <file> when the
221	                              `slti x0, x0, 0x5A1` exit marker retires; exit
222	                              with code 200.
223	  --hybrid-exit-pc <hex>      PC-trigger mode: drain when an insn at this PC
224	                              retires, instead of pre-scanning the ELF for
225	                              the `slti x0, x0, 0x5A1` exit marker. The binary
226	                              need not contain a marker HINT.
227	  --drain-minimal             At the exit drain, read back only mcycle and
228	                              minstret (the cycle figure), passing every other
229	                              field through from the resume snapshot. Skips the
230	                              full register-file readback (~190 DM abstract
231	                              commands). Use when the drained state is not
232	                              verified; the driver sets it when --verify is off.
233	  --no-reset-baseline         Disable the liveness gate: restore every
234	                              transported register instead of skipping the ones
235	                              already at the engine's reset value. Also skips
236	                              the one-time reset-state capture + cache
237	                              ($XDG_CACHE_HOME/andesim) a first run performs.
238	)");
239	  // --ilm/--dlm: CPU-specific, not all CPUs have ILM/DLM
240	  // --waveform: requires compile flag VSIMDEBUG
241	  // --save/--continue/--context-dir: requires compile flag VSIMSAVABLE
242	}
243	
244	// F3 probe helpers -- kept OUT of the generic sc_main lambda so their
245	// structured-binding / iostream / fmt code is compiled once, not re-instantiated
246	// per CPU class (a per-CPU instantiation inside the generic lambda tripped a
247	// clang ICE).
248	static auto read_probe_list(const std::string& path) -> std::vector<uint16_t>
249	{
250	  std::ifstream pf{path};
251	  if (!pf)
252	    throw std::runtime_error("--probe: cannot open " + path);
253	  std::vector<uint16_t> addrs;
254	  for (std::string line; std::getline(pf, line);) {
255	    const auto b = line.find_first_not_of(" \t\r");
256	    if (b == std::string::npos || line[b] == '#') continue;
257	    addrs.push_back(
258	      static_cast<uint16_t>(std::stoul(line.substr(b), nullptr, 16)));
259	  }
260	  return addrs;
261	}
262	
263	static void emit_probe_csv(
264	  const std::vector<std::pair<uint16_t, std::optional<uint64_t>>>& results)
265	{
266	  for (const auto& r: results) {
267	    if (r.second)
268	      fmt::print("0x{:03X},yes,0x{:016x}\n", r.first, *r.second);
269	    else
270	      fmt::print("0x{:03X},no,-\n", r.first);
271	  }
272	}
273	
274	extern "C" auto sc_main(const int argc, char* argv[]) -> int
275	try {
276	  spdlog::set_default_logger(spdlog::stderr_color_mt("stderr_logger"));
277	  spdlog::set_pattern("[%^%l%$] %v");
278	
279	  const auto args = [&] {
280	    struct args
281	    {
282	      std::string pc_trace_file{};
283	      std::string elf_file{};
284	      std::optional<uint16_t> jtag_port = std::nullopt;
285	      bool memmap = false;
