Extra Options (require additional license):
  --ilm       <image>         Load ILM ROM image
  --dlm       <image>         Load DLM ROM image
  --hvm       <image>         Load HVM (High-Bandwidth Vector Memory) image
  --waveform  <file>          Enable VCD/FST waveform tracing
  --save                      Save context when CPU enters WFI
  --continue                  Restore context and resume execution
  --context-dir <dir>         Context directory [default: ./saved_ctx]

Hybrid (QEMU + Verilator):
  --shared-mem-path <file>    mmap-backed file used as main RAM (zero-copy
                              shared with QEMU). Requires --shared-mem-size.
  --shared-mem-size <bytes>   Size of the shared mmap region; must cover the
                              full main memory range
  --shared-mem-base <hex>     Guest physical address that file offset 0 maps
                              to. Default 0x80000000 (QEMU virt RAM base);
                              override only for non-virt machine types.
  --resume-from-qemu <file>   Resume from a QEMU-side state snapshot.
                              Mutually exclusive with --continue.
  --handoff-out <file>        Drain architectural state to <file> when the
                              `slti x0, x0, 0x5A1` exit marker retires; exit
                              with code 200.
  --hybrid-exit-pc <hex>      PC-trigger mode: drain when an insn at this PC
                              retires, instead of pre-scanning the ELF for
                              the `slti x0, x0, 0x5A1` exit marker. The binary
                              need not contain a marker HINT.
  --drain-minimal             At the exit drain, read back only mcycle and
                              minstret (the cycle figure), passing every other
                              field through from the resume snapshot. Skips the
                              full register-file readback (~190 DM abstract
                              commands). Use when the drained state is not
                              verified; the driver sets it when --verify is off.
  --no-reset-baseline         Disable the liveness gate: restore every
                              transported register instead of skipping the ones
                              already at the engine's reset value. Also skips
                              the one-time reset-state capture + cache
                              ($XDG_CACHE_HOME/andesim) a first run performs.
)");
  // --ilm/--dlm: CPU-specific, not all CPUs have ILM/DLM
  // --waveform: requires compile flag VSIMDEBUG
  // --save/--continue/--context-dir: requires compile flag VSIMSAVABLE
}

// F3 probe helpers -- kept OUT of the generic sc_main lambda so their
// structured-binding / iostream / fmt code is compiled once, not re-instantiated
// per CPU class (a per-CPU instantiation inside the generic lambda tripped a
// clang ICE).
static auto read_probe_list(const std::string& path) -> std::vector<uint16_t>
{
  std::ifstream pf{path};
  if (!pf)
    throw std::runtime_error("--probe: cannot open " + path);
  std::vector<uint16_t> addrs;
  for (std::string line; std::getline(pf, line);) {
    const auto b = line.find_first_not_of(" \t\r");
    if (b == std::string::npos || line[b] == '#') continue;
    addrs.push_back(
      static_cast<uint16_t>(std::stoul(line.substr(b), nullptr, 16)));
  }
  return addrs;
}

static void emit_probe_csv(
  const std::vector<std::pair<uint16_t, std::optional<uint64_t>>>& results)
{
  for (const auto& r: results) {
    if (r.second)
      fmt::print("0x{:03X},yes,0x{:016x}\n", r.first, *r.second);
    else
      fmt::print("0x{:03X},no,-\n", r.first);
  }
}

