  ContextManager<CPU> context_config;

  Simulator(const sc_core::sc_module_name& name,
            std::span<uint8_t> ram_buffer = {},
            MemoryRegion ram_region = {RAM_BASE, RAM_END},
            MemoryRegion ram_alias_region = {RAM_ALIAS_BASE, RAM_ALIAS_END})
      : sc_core::sc_module{name},
        platform("platform", ram_buffer, ram_region, ram_alias_region),
        dtm(platform.dtm)
  {
    cpu.bind(platform.clk, platform.resetn, platform.reset_vector,
             platform.dmi_signals, platform.wfi_signal, platform.int_trigger);

    // --- CPU memory BFM → interconnect ---
    if constexpr (is_axi) {
      mem_bridge = make_axi_to_tlm("mem_bridge", cpu.mem_bfm.isckt);
      platform.interconnect.bind_initiator(mem_bridge->tlm_isck);
    } else {
      platform.interconnect.bind_initiator(cpu.mem_bfm.isckt);
    }

    // --- CPU MMIO BFM → interconnect ---
    if constexpr (requires { cpu.mmio_bfm; }) {
      if constexpr (is_axi) {
        mmio_bridge = make_axi_to_tlm("mmio_bridge", cpu.mmio_bfm.isckt);
        platform.interconnect.bind_initiator(mmio_bridge->tlm_isck);
      } else {
        platform.interconnect.bind_initiator(cpu.mmio_bfm.isckt);
      }
    }

    // --- CPU HVM subordinate port ---
    if constexpr (requires { cpu.hvm_bfm; }) {
      if constexpr (is_axi) {
        hvm_bridge = make_tlm_to_axi("hvm_bridge", cpu.hvm_bfm.tsckt);
        platform.interconnect.bind_target(
          hvm_bridge->tlm_tsck,
          {CPU::NDS_HVM_BASE,
           CPU::NDS_HVM_BASE + CPU::NDS_HVM_SIZE_KB * 0x1000 - 1});
      } else {
        platform.interconnect.bind_target(
          cpu.hvm_bfm.tsckt,
          {CPU::NDS_HVM_BASE,
           CPU::NDS_HVM_BASE + CPU::NDS_HVM_SIZE_KB * 0x1000 - 1});
      }
    }

    // --- CPU slave port ---
    if constexpr (requires { cpu.slv_bfm; }) {
      if constexpr (is_axi) {
        slv_bridge = make_tlm_to_axi("slv_bridge", cpu.slv_bfm.tsckt);
        platform.interconnect.bind_target(slv_bridge->tlm_tsck,
                                          {HART0_ILM_BASE, HART0_DLM_END});
      } else {
        platform.interconnect.bind_target(cpu.slv_bfm.tsckt,
                                          {HART0_ILM_BASE, HART0_DLM_END});
      }
    }

    // --- CPU sys bus (slave port, 64-bit) → interconnect ---
    if constexpr (requires { cpu.sys_bfm; }) {
      sys_adapter =
        std::make_unique<socket_width_adapter<bus_width, sys_bus_width>>(
          "sys_adapter");
      sys_bridge =
        std::make_unique<tlm_to_axi_bridge<sys_bus_width>>("sys_bridge");
      sys_bridge->pe.clk_i.bind(platform.clk);
      sys_bridge->axi_isck.bind(cpu.sys_bfm.tsckt);
      sys_adapter->isck.bind(sys_bridge->tlm_tsck);
      platform.interconnect.bind_target(sys_adapter->tsck,
                                        {MLIF_BASE, SLIF_END});
    }

#if _NDS_IOCP_NUM > 0
    iocp_master.protocol_engine.clk_i.bind(platform.clk);
    iocp_master.socket.bind(cpu.iocp_bfm.tsckt);
#endif // _NDS_IOCP_NUM
  }

  ~Simulator() { trace_.close(); }

  void init_debug_port(const uint16_t port = 9104)
  {
    dtm_debug = true;
    dtm.init_port(port);
    spdlog::info("waiting for debugger connection");
  }

  // Caller invariant: the CPU must already be out of reset.
  //
  // baseline_cache (LG3): path to this (engine build, ELF)'s reset-state
  // baseline; empty disables the liveness gate (transport-everything). On a
  // cache miss the baseline is captured HERE: the hart is freshly reset and
  // the capture drain halts it exactly where resume() would, so the drained
  // values ARE what the gate must compare restores against. Capture runs
  // BEFORE the scratch stagings below -- its drain sweeps dump reset
  // registers through the same scratch page the stagings fill.
  void apply_resume_from_qemu(const std::string& path,
                              const std::string& baseline_cache = {})
  {
    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width, PLATFORM::dmi_data_width>
      bus{platform.dmi, platform.clk.period()};
    hybrid_input_state_ = hybrid::load_state(path);

    std::optional<hybrid_state_v1> baseline{};
    bool baseline_captured = false;
    if (!baseline_cache.empty()) {
      baseline = hybrid::try_load_reset_baseline(baseline_cache);
      // Stale-shape insurance: a cache whose flags/vlenb no longer cover the
      // incoming state was captured under a different engine/QEMU pairing.
      if (baseline
          && ((baseline->flags & hybrid_input_state_->flags)
                != hybrid_input_state_->flags
              || baseline->vlenb != hybrid_input_state_->vlenb))
        baseline.reset();
      if (!baseline) {
        baseline = capture_reset_baseline(bus, *hybrid_input_state_);
        baseline_captured = true;
        if (!hybrid::save_reset_baseline(baseline_cache, *baseline))
          spdlog::warn("hybrid: cannot save reset baseline to {}",
                       baseline_cache);
      }
      spdlog::info("hybrid: reset baseline {} ({})",
                   baseline_captured
                     ? "captured -- one-time cost per engine build + ELF"
                     : "cache hit",
                   baseline_cache);
    }

    // Stage V-register bytes into the fixed scratch region of RAM BEFORE
    // resume: ResumeDriver's Program-Buffer reload sweep issues vle8.v from
    // this region to repopulate v0..v31, so the bytes must be in place first.
    // Best-effort: mismatched RAM layouts throw, which is louder than silently
    // dropping V state.
    if ((hybrid_input_state_->flags & HYBRID_FLAG_V) != 0u) {
      hybrid::stage_v_to_scratch(*hybrid_input_state_,
                                 platform.main_memory.data);
    }
    // GPR/FPR/CSR transport is Abstract-Command-only in BOTH directions (never
    // Program Buffer): a csrrw to a caps-supported but read-only / WARL-illegal
    // CSR raises cmderr, and the abstract path's per-CSR clear_cmderr tolerates
    // that single failure and moves on -- a batched PB sweep could not. The
    // Program Buffer carries only what abstract commands cannot reach: the V
    // data sweep, the Tier-B vsetvl, and the L2C MMIO window.
    const auto caps = active_caps();
    hybrid::ResumeDriver driver(bus, v_scratch_gpa(), caps);
    driver.set_l2c(l2c_present(), l2c_base());  // v5: restore L2C config if present
    // LG3: on a capture run the capture drain's V dump sweep clobbered
    // vtype/vl/vstart, so the vsetvl elision is only valid on cache hits.
    if (baseline)
      driver.set_reset_baseline(*baseline,
                                /*v_cfg_at_reset=*/!baseline_captured);
    std::size_t andes_mext_csrs = 0;
    hybrid::for_each_transport_csr(*hybrid_input_state_, caps,
      [&](uint16_t, const uint64_t&) { ++andes_mext_csrs; });
    const auto resume_t0 = sc_core::sc_time_stamp();
    const auto wall_t0 = std::chrono::steady_clock::now();
    driver.resume(*hybrid_input_state_);
    const auto wall_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
      std::chrono::steady_clock::now() - wall_t0).count();
    const auto resume_cycles = static_cast<uint64_t>(
      (sc_core::sc_time_stamp() - resume_t0) / platform.clk.period());
    spdlog::info("hybrid: resume={} cycles ({} ms wall), restore path="
                 "abstract, andes+m-ext csrs={}",
                 resume_cycles, wall_ms, andes_mext_csrs);
    if (baseline)
      spdlog::info("hybrid: liveness gate elided {} register restores",
                   driver.baseline_skip_count());
  }

