21	// HVM bank backdoor copy (HVM transport F1, ROADMAP_hvm): rows are wide
22	// Verilated words (VlWide<16> -- 16 independent 32-bit data lanes per row,
23	// no ECC/parity), a geometry lm_backdoor_read's one-word-per-row decode
24	// below cannot express, hence the separate pair. Lane k of a row holds
25	// bytes 4k..4k+3, little-endian (R2, pinned by the head/tail probes of
26	// tests/vsim/test_vsim_hvm_load.sh). `base` is the bank's byte offset into
27	// the image; the write zero-fills where the image does not reach. The two
28	// duals share the geometry so the byte order cannot drift.
29	void hvm_bank_write(auto& mem, size_t bank_bytes,
30	                    const std::vector<uint8_t>& data, size_t base)
31	{
32	  constexpr size_t lanes = sizeof(mem[0]) / sizeof(mem[0][0]);
33	  for (size_t row = 0; row < bank_bytes / (lanes * 4); ++row)
34	    for (size_t lane = 0; lane < lanes; ++lane) {
35	      uint32_t w = 0;
36	      for (size_t j = 0; j < 4; ++j) {
37	        const size_t idx = base + row * lanes * 4 + lane * 4 + j;
38	        if (idx < data.size())
39	          w |= static_cast<uint32_t>(data[idx]) << (j * 8);
40	      }
41	      mem[row][lane] = w;
42	    }
43	}
44	
45	void hvm_bank_read(auto& mem, size_t bank_bytes, uint8_t* out)
46	{
47	  constexpr size_t lanes = sizeof(mem[0]) / sizeof(mem[0][0]);
48	  for (size_t row = 0; row < bank_bytes / (lanes * 4); ++row)
49	    for (size_t lane = 0; lane < lanes; ++lane) {
50	      const uint32_t w = mem[row][lane];
51	      for (size_t j = 0; j < 4; ++j)
52	        out[row * lanes * 4 + lane * 4 + j] = static_cast<uint8_t>(w >> (j * 8));
53	    }
54	}
55	
56	// Decode a Verilated LM SRAM array back to raw little-endian bytes -- the
57	// shared read loop of get_ilm/get_dlm (data bits only, ECC/parity stripped).
58	// DataWidth/EccType mirror the setters' #if ladder; `if constexpr` keeps the
59	// VlWide [0]/[1] indexing uninstantiated on scalar-typed (no-ECC) configs.
60	template <int DataWidth, int EccType>
61	std::vector<uint8_t> lm_backdoor_read(auto& mem, size_t bytes)
62	{
63	  constexpr size_t word_size = DataWidth == 64 ? 8 : 4;
64	  using word_t = std::conditional_t<DataWidth == 64, uint64_t, uint32_t>;
65	  std::vector<uint8_t> out(bytes);
66	  for (size_t i = 0; i < bytes / word_size; ++i) {
67	    word_t word;
68	    if constexpr (EccType == 2 && DataWidth == 64)
69	      word = static_cast<word_t>(mem[i][0])
70	             | (static_cast<word_t>(mem[i][1]) << 32);
71	    else if constexpr (EccType == 2)
72	      word = static_cast<word_t>(mem[i] & 0xFFFFFFFFull);
73	    else
74	      word = static_cast<word_t>(mem[i]);
75	    for (size_t j = 0; j < word_size; ++j)
76	      out[i * word_size + j] = static_cast<uint8_t>(word >> (j * 8));
77	  }
78	  return out;
79	}
