435	  /**
436	   * @brief Set ILM (Instruction Local Memory) content with ECC/parity code
437	   * generation
438	   *
439	   * This function loads instruction data into the ILM and automatically
440	   * generates and appends ECC or parity codes based on the ILM_ECC_TYPE
441	   * configuration.
442	   *
443	   * Reference: external/ax45mpv_premium/testbench/ae350_tb.sv lines 1813-1853
444	   *
445	   * Supported configurations:
446	   * - rv32i + ecc: Appends 7-bit ECC code to bits [38:32]
447	   * - rv32i + parity: Appends 4-bit parity to bits [35:32]
448	   * - rv64i + ecc: Appends 8-bit ECC code to bits [71:64]
449	   * - rv64i + parity: Appends 8-bit parity to bits [71:64]
450	   * - none: No code generation, data written as-is
451	   *
452	   * @tparam SIZE ILM size in bytes (must match NDS_ILM_SIZE_KB * 1024)
453	   * @param data Vector of bytes to load into ILM (little-endian)
454	   */
455	  void set_ilm(const std::vector<uint8_t>& data)
456	  {
457	    if (data.size() > SIZE) {
458	      throw std::runtime_error("ILM data size (" + std::to_string(data.size())
459	                               + " bytes) exceeds ILM capacity ("
460	                               + std::to_string(SIZE) + " bytes)");
461	    }
462	
463	    constexpr bool is_64bit = (NDS_ILM_DATA_WIDTH == 64);
464	    constexpr size_t word_size = is_64bit ? 8 : 4;
465	    constexpr size_t word_count = SIZE / word_size;
466	    using word_t = std::conditional_t<is_64bit, uint64_t, uint32_t>;
467	
468	    spdlog::info("Setting ILM content: size={} bytes, XLEN={}, ECC_TYPE={}",
469	                 SIZE, NDS_XLEN, NDS_ILM_ECC_TYPE);
470	
471	    auto& mem =
472	      this
473	        ->rootp
474	#ifdef _NDS_IO_ILM_TL_UL
475	        ->ae350_vcpu_cluster_subsystem__DOT__gen_tl_ul_core0_ram0__DOT__u_ilm_tl_ul_core0_ram0__DOT__ram_inst__DOT__mem;
476	#else
477	        ->ae350_vcpu_cluster_subsystem__DOT__u_cluster__DOT__u_complex0__DOT__u_core0__DOT__u_ilm_ram0__DOT__ram_inst__DOT__mem;
478	#endif // _NDS_IO_ILM_TL_UL
479	
480	    for (size_t i = 0; i < word_count; ++i) {
481	      const size_t byte_idx = i * word_size;
482	
483	      // Read word (handle partial data with zero-fill)
484	      word_t word = 0;
485	      for (size_t j = 0; j < word_size && byte_idx + j < data.size(); ++j) {
486	        word |= static_cast<word_t>(data[byte_idx + j]) << (j * 8);
487	      }
488	
489	      // Generate and append ECC code
490	#if _NDS_ILM_ECC_TYPE_INT == 2
491	#if _NDS_ILM_DATA_WIDTH == 64
492	      VL_SET_WQ(mem[i], word);
493	      mem[i][2] = ecc::ecc64_gen(word);
494	#else // _NDS_ILM_DATA_WIDTH == 32
495	      mem[i] = (ecc::ecc32_gen(word) << 32) | word;
496	#endif
497	#else // no ECC
498	      mem[i] = word;
499	#endif
500	    }
501	
502	    spdlog::info("ILM loaded: {} x {}-bit words", word_count, word_size * 8);
503	  }
