604	   * @brief Read the DLM content back (dual of set_dlm) -- data bits only,
605	   * ECC/parity stripped. See get_ilm.
606	   */
607	  std::vector<uint8_t> get_dlm()
608	  {
609	    auto& mem =
610	      this
611	        ->rootp
612	#ifdef _NDS_IO_DLM_TL_UL
613	        ->ae350_vcpu_cluster_subsystem__DOT__u_core0_dlm_ram0__DOT__ram_inst__DOT__mem;
614	#else
615	        ->ae350_vcpu_cluster_subsystem__DOT__u_cluster__DOT__u_complex0__DOT__u_core0__DOT__u_dlm_ram0__DOT__ram_inst__DOT__mem;
616	#endif // _NDS_IO_DLM_TL_UL
617	
618	#if _NDS_DLM_ECC_TYPE_INT == 2
619	    return lm_backdoor_read<NDS_DLM_DATA_WIDTH, 2>(mem, SIZE);
620	#else
621	    return lm_backdoor_read<NDS_DLM_DATA_WIDTH, 0>(mem, SIZE);
622	#endif
623	  }
624	#undef SIZE
625	#endif // _NDS_DLM_SIZE_KB > 0
626	
627	#if defined(_NDS_IO_HVM0) && defined(_NDS_IO_HVM1)
628	#define SIZE (_NDS_HVM_SIZE_KB * 1024)
629	  /**
630	   * @brief Load HVM (High-Bandwidth Vector Memory) content -- zero-sim-cycle
631	   * hierarchical-reference write, the --hvm backdoor (HVM transport F1,
632	   * ROADMAP_hvm).
633	   *
634	   * Premium geometry: 2 banks at cluster level
635	   * (u_ae350_hvm_ram_subsystem), bank = byte-address bit
636	   * _NDS_HVM_ADDR_BANK_BIT (bank0 = low half, bank1 = high half), rows of
637	   * VlWide<16> (512 data bits), no ECC/parity -- unlike ILM/DLM there is no
638	   * code generation and no enable bit. Zero-fills past data.size() like
639	   * set_ilm/set_dlm.
640	   *
641	   * @param data Bytes to load (little-endian), size <= SIZE bytes
642	   */
643	  void set_hvm(const std::vector<uint8_t>& data)
644	  {
645	    if (data.size() > SIZE) {
646	      throw std::runtime_error("HVM data size (" + std::to_string(data.size())
647	                               + " bytes) exceeds HVM capacity ("
648	                               + std::to_string(SIZE) + " bytes)");
649	    }
650	
651	    constexpr size_t bank_bytes = size_t{1} << _NDS_HVM_ADDR_BANK_BIT;
652	    static_assert(_NDS_HVM_BANKS == 2 && 2 * bank_bytes == SIZE,
653	                  "HVM bank split must cover the whole memory");
654	
655	    spdlog::info("Setting HVM content: size={} bytes, banks={}", SIZE,
656	                 _NDS_HVM_BANKS);
657	
658	    auto& b0 =
659	      this->rootp
660	        ->ae350_vcpu_cluster_subsystem__DOT__u_ae350_hvm_ram_subsystem__DOT__u_hvm0_ram__DOT__ram_inst__DOT__mem;
661	    auto& b1 =
662	      this->rootp
663	        ->ae350_vcpu_cluster_subsystem__DOT__u_ae350_hvm_ram_subsystem__DOT__u_hvm1_ram__DOT__ram_inst__DOT__mem;
664	
665	    hvm_bank_write(b0, bank_bytes, data, 0);
666	    hvm_bank_write(b1, bank_bytes, data, bank_bytes);
667	  }
668	
669	  /**
670	   * @brief Read the HVM content back (dual of set_hvm) -- zero sim cycles.
671	   * Used by the hybrid exit drain to dump the .hvm sidecar.
672	   */
673	  std::vector<uint8_t> get_hvm()
674	  {
675	    constexpr size_t bank_bytes = size_t{1} << _NDS_HVM_ADDR_BANK_BIT;
676	    std::vector<uint8_t> out(SIZE);
677	
678	    auto& b0 =
679	      this->rootp
680	        ->ae350_vcpu_cluster_subsystem__DOT__u_ae350_hvm_ram_subsystem__DOT__u_hvm0_ram__DOT__ram_inst__DOT__mem;
681	    auto& b1 =
682	      this->rootp
683	        ->ae350_vcpu_cluster_subsystem__DOT__u_ae350_hvm_ram_subsystem__DOT__u_hvm1_ram__DOT__ram_inst__DOT__mem;
684	
685	    hvm_bank_read(b0, bank_bytes, out.data());
686	    hvm_bank_read(b1, bank_bytes, out.data() + bank_bytes);
687	    return out;
688	  }
689	#undef SIZE
690	#endif // _NDS_IO_HVM0 && _NDS_IO_HVM1
691	
692	  // Returns all committed PCs from all cores and all issue slots
693	  // Result: vector[core_id] contains vector of committed PCs for that core
694	  // Each inner vector has 0-2 entries depending on how many instructions
695	  // committed (ax45mpv is 2-issue)
696	  std::vector<std::vector<uint64_t>> get_committed_pc()
697	  {
698	    std::vector<std::vector<uint64_t>> result(_NDS_NHART);
699	
700	    // Core 0 - 2 issue slots
701	    if (this->rootp->WB_I0_RETIRE_C0) {
702	      result[0].push_back(this->rootp->WB_I0_PC_C0);
703	    }
704	    if (this->rootp->WB_I1_RETIRE_C0) {
