                               + " bytes) exceeds HVM capacity ("
                               + std::to_string(SIZE) + " bytes)");
    }

    constexpr size_t bank_bytes = size_t{1} << _NDS_HVM_ADDR_BANK_BIT;
    static_assert(_NDS_HVM_BANKS == 2 && 2 * bank_bytes == SIZE,
                  "HVM bank split must cover the whole memory");

    spdlog::info("Setting HVM content: size={} bytes, banks={}", SIZE,
                 _NDS_HVM_BANKS);

    auto& b0 =
      this->rootp
        ->ae350_vcpu_cluster_subsystem__DOT__u_ae350_hvm_ram_subsystem__DOT__u_hvm0_ram__DOT__ram_inst__DOT__mem;
    auto& b1 =
      this->rootp
        ->ae350_vcpu_cluster_subsystem__DOT__u_ae350_hvm_ram_subsystem__DOT__u_hvm1_ram__DOT__ram_inst__DOT__mem;

    hvm_bank_write(b0, bank_bytes, data, 0);
    hvm_bank_write(b1, bank_bytes, data, bank_bytes);
