    std::vector<uint8_t> out(SIZE);

    auto& b0 =
      this->rootp
        ->ae350_vcpu_cluster_subsystem__DOT__u_ae350_hvm_ram_subsystem__DOT__u_hvm0_ram__DOT__ram_inst__DOT__mem;
